def transform(grid):
    # Fill blank cells when all observed nonzero cells have one color.
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) == 1:
        c = next(iter(colors))
        return [[c if v == 0 else v for v in row] for row in grid]
    return [row[:] for row in grid]
